/* ttrend_outline - see ../include/ttrend_outline.h.
 *
 * Pipeline per glyph:
 *   cmap -> gid -> outline (glyf or CFF Type 2) -> path in 16.16 font units
 *   -> scale / sub-pixel shift -> exact-area scanline rasteriser (signed area
 *   accumulation, 16.16 fixed point) -> 8-bit coverage -> cache -> blend.
 * Everything is integer maths. */


