static long tto_mos_read(long fd, void* buf, size_t len) { return (long)read((int)fd, buf, len); }
static long tto_mos_close(long fd) { return (long)close((int)fd); }
static long tto_mos_size(long fd) {
    struct stat st;
    return fstat((int)fd, &st) == 0 ? (long)st.st_size : -1;
}
#else
extern long mos_open(const char* path, long flags);
extern long mos_read(long fd, void* buf, size_t len);
