extern long mos_size(long fd);
static long tto_mos_open(const char* path) { return mos_open(path, 0); }
static long tto_mos_read(long fd, void* buf, size_t len) { return mos_read(fd, buf, len); }
static long tto_mos_close(long fd) { return mos_close(fd); }
static long tto_mos_size(long fd) { return mos_size(fd); }
